// ============================== motor dos traços (relógio por quadro) ==============================
const _CAD = { tracos: [], canetas: [], ligado: false };
const _cadEl = (pai, tag, at = {}) => { const e = document.createElementNS(NS, tag); for (const k in at) e.setAttribute(k, at[k]); pai.appendChild(e); return e; };
const _cadSs = (u) => { u = Math.max(0, Math.min(1, u)); return u * u * (3 - 2 * u); };
function _cadQuadro(t) {
  for (const s of _CAD.tracos) {
    const p = s.te <= s.ts ? (t >= s.ts ? 1 : 0) : Math.max(0, Math.min(1, (t - s.ts) / (s.te - s.ts)));
    if (p !== s.p) { s.p = p; if (p <= 0) s.el.setAttribute("visibility", "hidden"); else { s.el.setAttribute("visibility", "visible"); s.el.setAttribute("stroke-dashoffset", (s.len * (1 - p)).toFixed(1)); } }
  }
  for (const c of _CAD.canetas) c.atualiza(t);
}
// um traço: pts absolutos na página; o = { cor, w, ts, te, op, pai, caneta }
function _cadTraco(pg, pts, o) {
  if (pts.length < 2) pts = [pts[0], [pts[0][0] + 0.2, pts[0][1] + 0.2]];
  const cum = [0]; for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const len = cum[cum.length - 1] + 0.01;
  const el = _cadEl(o.pai || pg.gTexto, "path", { d: "M" + pts.map((p) => p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" L"), fill: "none", stroke: o.cor || CAD_TINTA, "stroke-width": (o.w ?? 4).toFixed(2), "stroke-linecap": "round", "stroke-linejoin": "round",
    "stroke-dasharray": `${len.toFixed(1)} ${(len + 20).toFixed(1)}`, "stroke-dashoffset": len.toFixed(1), visibility: "hidden" });
  if (o.op != null) el.setAttribute("opacity", o.op);
  const s = { el, len, ts: o.ts, te: o.te, p: -1, pts, cum };
  _CAD.tracos.push(s); if (o.caneta !== false) pg.pen.lista.push(s);
  if (!_CAD.ligado) { _CAD.ligado = true; aCadaQuadro(_cadQuadro); }
  return s;
}
// a caneta: segue o traço que está sendo escrito, desliza até o próximo e some quando a mão descansa
function _cadCaneta(pg) {
  const g = _cadEl(pg.g, "g", { visibility: "hidden" }), corpo = _cadEl(g, "g", { transform: "rotate(24)" });
  _cadEl(corpo, "path", { d: "M7 8 L-1 -22 L-19 -22 L-9 8 Z", fill: "rgba(40,30,20,0.16)", transform: "translate(9 7)" });
  _cadEl(corpo, "path", { d: "M0 0 L-6 -24 L6 -24 Z", fill: "#e9dcc0", stroke: "#8a7a5a", "stroke-width": 1.4, "stroke-linejoin": "round" });
  _cadEl(corpo, "rect", { x: -9, y: -190, width: 18, height: 168, rx: 7, fill: "#2b3f8e" });
  _cadEl(corpo, "rect", { x: -9, y: -190, width: 6, height: 168, rx: 3, fill: "#4a63bd", opacity: 0.55 });
  _cadEl(corpo, "rect", { x: -9.5, y: -62, width: 19, height: 7, fill: CAD_OURO });
  _cadEl(corpo, "path", { d: "M9 -186 L15 -186 L15 -120 L9 -126", fill: "#c9921a" });
  const C = { g, lista: [], ord: false, atualiza(t) {
    if (!C.ord) { C.lista.sort((a, b) => a.ts - b.ts); C.ord = true; }
    const L = C.lista; let k = -1; for (let i = 0; i < L.length; i++) { if (L[i].ts <= t) k = i; else break; }
    if (k < 0) return g.setAttribute("visibility", "hidden");
    const s = L[k]; let x, y, op = 1;
    const em = (q) => { const f = Math.max(0, Math.min(1, (t - q.ts) / Math.max(0.001, q.te - q.ts))) * q.len; let j = 1; while (j < q.cum.length - 1 && q.cum[j] < f) j++; const a = q.pts[j - 1], b = q.pts[j], u = (f - q.cum[j - 1]) / Math.max(0.001, q.cum[j] - q.cum[j - 1]); return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u]; };
    if (t < s.te) [x, y] = em(s);
    else { const n = L[k + 1], fim = s.pts[s.pts.length - 1];
      if (n && n.ts - s.te < 1.4) { const u = _cadSs((t - s.te) / Math.max(0.05, n.ts - s.te)), q0 = n.pts[0]; x = fim[0] + (q0[0] - fim[0]) * u; y = fim[1] + (q0[1] - fim[1]) * u - 26 * Math.sin(Math.PI * u); }
      else { x = fim[0]; y = fim[1]; op = Math.max(0, 1 - (t - s.te - 0.35) / 0.4); } }
    if (op <= 0.01) return g.setAttribute("visibility", "hidden");
    g.setAttribute("visibility", "visible"); g.setAttribute("opacity", op.toFixed(2)); g.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
  } };
  _CAD.canetas.push(C); return C;
}

