  _cadEl(g, "rect", { x: -200, y: -200, width: 1480, height: 2320, fill: `url(#cadLuz${o.seed ?? 5})` });
  for (let k = 0; k < 160; k++) _cadEl(g, "circle", { cx: (r() * 1280 - 100).toFixed(0), cy: (r() * 2100 - 100).toFixed(0), r: (0.8 + r() * 2).toFixed(1), fill: "#8a7448", opacity: (0.04 + r() * 0.08).toFixed(2) });
  for (let k = 0; k < 40; k++) { const x = r() * 1280 - 100, y = r() * 2100 - 100, a = r() * 6.28, l = 12 + r() * 30; _cadEl(g, "line", { x1: x.toFixed(0), y1: y.toFixed(0), x2: (x + Math.cos(a) * l).toFixed(0), y2: (y + Math.sin(a) * l).toFixed(0), stroke: "#a38d5c", "stroke-width": 1, opacity: 0.1 }); }
